7	  bluePace: number[];
8	}
9	
10	export default function PaceChart({ time, duration, r1End, height = 150, redPace, bluePace }: PaceChartProps) {
11	  const W = 900, H = height, padB = 22, padT = 12;
12	  const n = redPace.length;
13	  if (n < 2) return null;
14	
15	  const maxY = Math.max(4, ...redPace, ...bluePace);
16	  const x = (i: number) => (i / (n - 1)) * W;
17	  const y = (v: number) => H - padB - (v / maxY) * (H - padB - padT);
18	  const line = (arr: number[]) =>
19	    arr.map((v, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ');
20	  const area = (arr: number[]) => `${line(arr)} L${W},${H - padB} L0,${H - padB} Z`;
21	  const r1x = duration > 0 ? (r1End / duration) * W : W / 2;
22	  const nowx = duration > 0 ? Math.min((time / duration) * W, W) : 0;
23	
24	  return (
25	    <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={height} preserveAspectRatio="none" style={{ display: 'block', overflow: 'visible' }}>
26	      <defs>
27	        <linearGradient id="pg-red" x1="0" y1="0" x2="0" y2="1">
28	          <stop offset="0%" stopColor="var(--f-red)" stopOpacity="0.35" />
29	          <stop offset="100%" stopColor="var(--f-red)" stopOpacity="0" />
30	        </linearGradient>
31	        <linearGradient id="pg-blue" x1="0" y1="0" x2="0" y2="1">
32	          <stop offset="0%" stopColor="var(--f-blue)" stopOpacity="0.35" />
33	          <stop offset="100%" stopColor="var(--f-blue)" stopOpacity="0" />
34	        </linearGradient>
35	      </defs>
36	      <line x1={r1x} y1={padT - 4} x2={r1x} y2={H - padB} stroke="var(--green-500)" strokeOpacity="0.4" strokeDasharray="4 4" />
37	      <text x={6} y={padT + 4} fill="var(--text-disabled)" fontSize="10" fontWeight="700">R1</text>
38	      <text x={r1x + 6} y={padT + 4} fill="var(--text-disabled)" fontSize="10" fontWeight="700">R2</text>
39	      <path d={area(redPace)} fill="url(#pg-red)" />
40	      <path d={area(bluePace)} fill="url(#pg-blue)" />
41	      <path d={line(redPace)} fill="none" stroke="var(--f-red)" strokeWidth="2.5" />
42	      <path d={line(bluePace)} fill="none" stroke="var(--f-blue)" strokeWidth="2.5" />
43	      {duration > 0 && (
44	        <>
45	          <line x1={nowx} y1={padT - 4} x2={nowx} y2={H - padB} stroke="var(--accent)" strokeWidth="1.5" />
46	          <circle cx={nowx} cy={padT - 4} r="3" fill="var(--accent)" />
47	        </>
48	      )}
49	      <line x1="0" y1={H - padB} x2={W} y2={H - padB} stroke="rgba(255,255,255,0.08)" />
50	    </svg>
51	  );
52	}
