export type Status = 'good' | 'warning' | 'critical' | 'unverified' | 'none' | 'circular';

/**
 * Icon + text always paired, never colour alone — good/critical collapse for
 * red-green colourblindness, and critical's red is close to the red corner.
 * `good`/`warning` use their own hex rather than the app's `--green-500`/
 * `--red-500` tokens: those are already claimed by other meanings
 * (training_data purpose, round spans) — see memory "frontend-palette-collisions".
 */
const STATUS: Record<Status, { color: string; icon: string }> = {
  good: { color: '#0ca30c', icon: 'check_circle' },
  warning: { color: '#fab219', icon: 'warning' },
  critical: { color: 'var(--red-500)', icon: 'error' },
  unverified: { color: 'var(--text-muted)', icon: 'help' },
  none: { color: 'var(--text-muted)', icon: 'remove' },
  circular: { color: '#b39dfb', icon: 'sync_problem' },
};

interface StatusBadgeProps {
  status: Status;
  children: React.ReactNode;
  size?: 'sm' | 'md';
  title?: string;
}

export default function StatusBadge({ status, children, size = 'md', title }: StatusBadgeProps) {
  const s = STATUS[status];
  const sm = size === 'sm';
  return (
    <span
      title={title}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: sm ? 4 : 5,
        flexShrink: 0,
        whiteSpace: 'nowrap',
        padding: sm ? '2px 6px 2px 5px' : '3px 8px 3px 6px',
        borderRadius: 6,
        background: `color-mix(in srgb, ${s.color} 13%, transparent)`,
        border: `1px solid color-mix(in srgb, ${s.color} 26%, transparent)`,
        color: s.color,
        fontSize: sm ? 10 : 11,
        fontWeight: 700,
        letterSpacing: '0.01em',
      }}
    >
      <span className="material-symbols-outlined" style={{ fontSize: sm ? 11 : 13 }}>{s.icon}</span>
      {children}
    </span>
  );
}

import { useState } from 'react';
import type { Fight } from '../../types/Fight';
import type { FixtureSummary } from '../../types/EvalRun';
import { createEvalRun } from '../../services/api';

interface NotMeasurableProps {
  fixture: FixtureSummary;
  /** Every `purpose='ai_labeled', state='completed'` fight — candidates to
   * score against this fixture. Passed down rather than fetched here so the
   * page fetches the fight list once and shares it across fixtures. */
  candidates: Fight[];
  onScored: () => void;
}

const videoStem = (path: string) => path.split('/').pop()?.replace(/\.[^.]+$/, '') ?? path;

/**
 * Section E's "E0" state (design brief §10): a labelled fixture with zero
 * eval_runs rows. Says so plainly instead of showing zeros, and gives both
 * the exact CLI command and a one-click "Run scoring" action when a
 * candidate ai_labeled fight already exists.
 */
export default function NotMeasurable({ fixture, candidates, onScored }: NotMeasurableProps) {
  const [picked, setPicked] = useState<number | ''>('');
  const [running, setRunning] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const cmd = `python -m eval.cli score-pair --labels-fight-id ${fixture.reference_fight_id} --predictions-fight-id <ai_labeled fight id> --write-db`;

  const run = async () => {
    if (picked === '') return;
    setRunning(true);
    setError(null);
    try {
      await createEvalRun(fixture.reference_fight_id, picked);
      onScored();
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Scoring failed');
    } finally {
      setRunning(false);
    }
  };

  return (
    <div style={{
      display: 'grid', placeItems: 'center', gap: 12, padding: '40px 24px',
      borderRadius: 12, background: 'rgba(255,255,255,0.018)',
      border: '1px dashed rgba(255,255,255,0.14)', textAlign: 'center',
    }}>
      <span className="material-symbols-outlined" style={{ fontSize: 34, color: 'var(--text-disabled)' }}>help</span>
      <p style={{ margin: 0, maxWidth: '46ch', fontSize: 13, lineHeight: 1.6, fontWeight: 600, color: 'var(--text-secondary)' }}>
        <strong>Strike accuracy isn't measurable yet</strong> for {videoStem(fixture.video_path)}.
        Re-run this source video through the AI pipeline (upload it again as an
        "AI annotation" fight) to make it an evaluation fixture, then score it
        against these labels — keep it out of the training set.
      </p>
      {candidates.length > 0 ? (
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', justifyContent: 'center' }}>
          <select
            value={picked}
            onChange={(e) => setPicked(e.target.value === '' ? '' : Number(e.target.value))}
            className="btn-glass"
            style={{ padding: '7px 10px', fontSize: 12, fontWeight: 600 }}
          >
            <option value="">Choose an AI-processed fight…</option>
            {candidates.map((f) => (
              <option key={f.id} value={f.id}>#{f.id} · {videoStem(f.video_path)}</option>
            ))}
          </select>
          <button
            type="button"
            className="btn-primary"
            disabled={picked === '' || running}
            onClick={run}
            style={{
              background: 'linear-gradient(135deg, #00daf3 0%, #0099b0 100%)',
              color: '#001f24', fontWeight: 700, fontSize: 12, padding: '7px 16px',
              borderRadius: 8, opacity: picked === '' || running ? 0.5 : 1,
            }}
          >
            {running ? 'Scoring…' : 'Run scoring'}
          </button>
        </div>
      ) : (
        <div style={{ fontSize: 11.5, fontWeight: 600, color: 'var(--text-muted)' }}>
          No completed AI-processed fight exists yet to score.
        </div>
      )}
      {error && <div style={{ fontSize: 11.5, fontWeight: 600, color: 'var(--red-500)' }}>{error}</div>}
      <code style={{
        display: 'block', maxWidth: '100%', overflowX: 'auto', padding: '8px 12px',
        borderRadius: 8, background: 'rgba(0,0,0,0.42)', border: '1px solid var(--border-subtle)',
        fontSize: 11, color: '#9fe8f4', whiteSpace: 'pre',
      }}>
        {cmd}
      </code>
    </div>
  );
}

import type { EvalRunSummary } from '../../types/EvalRun';
import StatusBadge from './StatusBadge';

interface ChangeTileProps {
  current: EvalRunSummary;
  previous: EvalRunSummary | null;
}

/**
 * F1 delta vs the immediately preceding run for this fixture. Greys out
 * (rather than colouring green/red) whenever the two runs aren't honestly
 * comparable — different tolerance, or the matching constants changed —
 * per the design brief's honesty rule 8.
 */
export default function ChangeTile({ current, previous }: ChangeTileProps) {
  if (!previous) {
    return (
      <div className="inner-tile" style={{ padding: '13px 15px', flex: 1, minWidth: 160 }}>
        <div className="label" style={{ marginBottom: 9 }}>Change</div>
        <StatusBadge status="none" size="sm">First run — nothing to compare</StatusBadge>
      </div>
    );
  }

  const comparable = previous.tolerance_frames === current.tolerance_frames;
  const constantsChanged = previous.constants_sha256 !== current.constants_sha256;
  const delta = (current.f1 ?? 0) - (previous.f1 ?? 0);
  const deltaColor = !comparable
    ? 'var(--text-tertiary)'
    : delta > 0 ? '#0ca30c' : delta < 0 ? 'var(--red-500)' : 'var(--text-tertiary)';

  return (
    <div className="inner-tile" style={{ padding: '13px 15px', flex: 1, minWidth: 160 }}>
      <div className="label" style={{ marginBottom: 9 }}>Change</div>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8 }}>
        <span style={{ fontSize: 20, fontWeight: 800, fontVariantNumeric: 'tabular-nums', color: deltaColor }}>
          {delta > 0 ? '+' : ''}{delta.toFixed(1)} pts
        </span>
        <span style={{ fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>vs {previous.git_sha.slice(0, 7)}</span>
      </div>
      {!comparable && (
        <div style={{ marginTop: 6, fontSize: 10, fontWeight: 600, color: '#fab219' }}>
          Tolerance changed (±{previous.tolerance_frames}f → ±{current.tolerance_frames}f) — not strictly comparable.
        </div>
      )}
      {comparable && constantsChanged && (
        <div style={{ marginTop: 6, fontSize: 10, fontWeight: 600, color: '#fab219' }}>
          Matching constants changed at this version — compare with care.
        </div>
      )}
    </div>
  );
}

import AccGauge from '../player/AccGauge';
import MiniStat from '../player/MiniStat';
import type { EvalRunSummary } from '../../types/EvalRun';
import ChangeTile from './ChangeTile';

interface HeadlineF1Props {
  /** Chronological, oldest first — last element is "current". */
  runs: EvalRunSummary[];
}

/** Section E1 — the headline stat group: F1 ring, P/R/TP/FP/FN/n tiles, and
 * the change-vs-previous-run tile. Reuses the Player's AccGauge/MiniStat
 * rather than inventing new stat primitives. */
export default function HeadlineF1({ runs }: HeadlineF1Props) {
  const current = runs[runs.length - 1];
  const previous = runs.length > 1 ? runs[runs.length - 2] : null;
  const labelled = (current.tp ?? 0) + (current.fn ?? 0);
  const predicted = (current.tp ?? 0) + (current.fp ?? 0);

  return (
    <div style={{ display: 'grid', gridTemplateColumns: 'auto 1fr 1fr', gap: 14, alignItems: 'stretch' }}>
      <div className="inner-tile" style={{ padding: '16px 20px', display: 'flex', alignItems: 'center', gap: 16 }}>
        <AccGauge pct={Math.round(current.f1 ?? 0)} color="var(--cyan-400)" label="Strike F1" />
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-tertiary)', fontVariantNumeric: 'tabular-nums' }}>
            P {current.precision}% · R {current.recall}%
          </span>
          <span style={{ fontSize: 11, fontWeight: 600, color: 'var(--text-muted)', fontVariantNumeric: 'tabular-nums' }}>
            TP {current.tp} · FP {current.fp} · FN {current.fn}
          </span>
          <span style={{ fontSize: 11, fontWeight: 600, color: 'var(--text-muted)' }}>
            {labelled} labelled · {predicted} predicted
          </span>
        </div>
      </div>
      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap' }}>
        <MiniStat value={`${current.offset_bias_frames ?? '—'}${current.offset_bias_frames != null ? 'f' : ''}`} label="Timing bias" />
        <MiniStat value={`${current.offset_jitter_frames ?? '—'}${current.offset_jitter_frames != null ? 'f' : ''}`} label="Timing jitter" />
        <MiniStat value={current.scored_minutes.toFixed(1)} label="Minutes scored" />
      </div>
      <ChangeTile current={current} previous={previous} />
    </div>
  );
}

import type { FixtureSummary } from '../../types/EvalRun';
import StatusBadge from './StatusBadge';

interface FixtureTableProps {
  fixtures: FixtureSummary[];
  selectedId: number | null;
  onSelect: (referenceFightId: number) => void;
}

const videoStem = (path: string) => path.split('/').pop()?.replace(/\.[^.]+$/, '') ?? path;

/** Section E2 — one row per fixture (a labelled `purpose='reference'` fight),
 * showing its latest scored run. Click a row to drill into E1/E8 for it. */
export default function FixtureTable({ fixtures, selectedId, onSelect }: FixtureTableProps) {
  return (
    <div style={{ overflowX: 'auto' }}>
      <table className="lab-table" style={{ width: '100%', borderCollapse: 'collapse', minWidth: 640 }}>
        <thead>
          <tr>
            {['Fixture', 'Labelled', 'Predicted', 'TP / FP / FN', 'P', 'R', 'F1', 'Bias · jitter', 'Scored at'].map((h, i) => (
              <th key={h} style={{
                textAlign: i === 0 ? 'left' : 'right', padding: '7px 10px', fontSize: 9.5, fontWeight: 800,
                textTransform: 'uppercase', letterSpacing: '0.09em', color: 'rgba(255,255,255,0.3)',
                borderBottom: '1px solid rgba(255,255,255,0.08)', whiteSpace: 'nowrap',
              }}>{h}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {fixtures.map((fx) => {
            const r = fx.latest_run;
            const labelled = r ? (r.tp ?? 0) + (r.fn ?? 0) : null;
            const predicted = r ? (r.tp ?? 0) + (r.fp ?? 0) : null;
            return (
              <tr
                key={fx.reference_fight_id}
                onClick={() => onSelect(fx.reference_fight_id)}
                style={{
                  cursor: 'pointer',
                  background: selectedId === fx.reference_fight_id ? 'rgba(0,218,243,0.045)' : 'transparent',
                }}
              >
                <td style={{ padding: '9px 10px', fontSize: 12.5, fontWeight: 700, color: 'var(--text-primary)', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                  #{fx.reference_fight_id} · {videoStem(fx.video_path)}
                </td>
                {!fx.is_measurable ? (
                  <td colSpan={7} style={{ padding: '9px 10px', borderBottom: '1px solid rgba(255,255,255,0.04)' }}>
                    <StatusBadge status="none" size="sm">Not scorable — no evaluation fixture yet</StatusBadge>
                  </td>
                ) : (
                  <>
                    <Cell>{labelled}</Cell>
                    <Cell>{predicted}</Cell>
                    <Cell>{r?.tp} / {r?.fp} / {r?.fn}</Cell>
                    <Cell>{r?.precision}%</Cell>
                    <Cell>{r?.recall}%</Cell>
                    <Cell><b style={{ fontWeight: 800, color: 'var(--text-primary)' }}>{r?.f1}%</b></Cell>
                    <Cell>{r?.offset_bias_frames ?? '—'} · {r?.offset_jitter_frames ?? '—'}</Cell>
                    <Cell>{r?.git_sha.slice(0, 7)}</Cell>
                  </>
                )}
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}

function Cell({ children }: { children: React.ReactNode }) {
  return (
    <td style={{
      padding: '9px 10px', textAlign: 'right', fontSize: 11.5, fontWeight: 600,
      color: 'var(--text-tertiary)', fontVariantNumeric: 'tabular-nums',
      borderBottom: '1px solid rgba(255,255,255,0.04)', whiteSpace: 'nowrap',
    }}>
      {children}
    </td>
  );
}

import type { EvalRunSummary } from '../../types/EvalRun';

interface VersionTrendChartProps {
  /** Chronological, oldest first. */
  runs: EvalRunSummary[];
}

const shortDate = (iso: string) =>
  new Date(iso).toLocaleDateString(undefined, { day: 'numeric', month: 'short' });

/**
 * Section E8 — F1/P/R across pipeline versions for one fixture. A hollow
 * marker means the matching constants changed at that version (compare with
 * care); a dashed vertical rule marks a run scored at a different tolerance
 * from the one before it (not directly comparable — honesty rule 8).
 */
export default function VersionTrendChart({ runs }: VersionTrendChartProps) {
  const W = 640, H = 160, padL = 28, padR = 20, padT = 14, padB = 34;
  const n = runs.length;
  if (n < 1) return null;

  const x = (i: number) => n === 1 ? W / 2 : padL + (i / (n - 1)) * (W - padL - padR);
  const y = (v: number) => H - padB - (v / 100) * (H - padB - padT);
  const line = (key: 'f1' | 'precision' | 'recall') =>
    runs.map((r, i) => `${i === 0 ? 'M' : 'L'}${x(i).toFixed(1)},${y(r[key] ?? 0).toFixed(1)}`).join(' ');

  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} preserveAspectRatio="xMidYMid meet" style={{ display: 'block', overflow: 'visible' }}>
        {[0, 25, 50, 75, 100].map((g) => (
          <line key={g} x1={padL} x2={W - padR} y1={y(g)} y2={y(g)} stroke="rgba(255,255,255,0.06)" strokeWidth="1" />
        ))}
        {runs.map((r, i) => (
          i > 0 && r.tolerance_frames !== runs[i - 1].tolerance_frames && (
            <line key={`tol-${r.id}`} x1={x(i)} x2={x(i)} y1={padT} y2={H - padB}
              stroke="rgba(250,178,25,0.5)" strokeWidth="1" strokeDasharray="3 3" />
          )
        ))}
        <path d={line('precision')} fill="none" stroke="rgba(0,218,243,0.3)" strokeWidth="1.5" strokeDasharray="3 3" />
        <path d={line('recall')} fill="none" stroke="rgba(179,157,251,0.5)" strokeWidth="1.5" strokeDasharray="3 3" />
        <path d={line('f1')} fill="none" stroke="var(--cyan-400)" strokeWidth="2" />
        {runs.map((r, i) => {
          const constantsChanged = i > 0 && r.constants_sha256 !== runs[i - 1].constants_sha256;
          return (
            <circle key={r.id} cx={x(i)} cy={y(r.f1 ?? 0)} r={i === n - 1 ? 5 : 3.5}
              fill={constantsChanged ? '#0b1417' : 'var(--cyan-400)'}
              stroke="var(--cyan-400)" strokeWidth={i === n - 1 ? 2.5 : 1.5}>
              <title>{r.git_sha.slice(0, 7)} · {shortDate(r.generated_at)} · F1 {r.f1}% · P {r.precision}% · R {r.recall}%{constantsChanged ? ' · constants changed' : ''}</title>
            </circle>
          );
        })}
      </svg>
      <div style={{ position: 'relative', height: 34, marginTop: 2 }}>
        {runs.map((r, i) => (
          <div key={r.id} style={{
            position: 'absolute', top: 0, left: `${(x(i) / W) * 100}%`, transform: 'translateX(-50%)',
            textAlign: 'center', whiteSpace: 'nowrap',
          }}>
            <div style={{ fontFamily: 'ui-monospace,Menlo,monospace', fontSize: 10, fontWeight: 700, color: i === n - 1 ? '#9fe8f4' : 'var(--text-muted)' }}>
              {r.git_sha.slice(0, 7)}
            </div>
            <div style={{ fontSize: 9, fontWeight: 600, color: 'var(--text-disabled)' }}>{shortDate(r.generated_at)}</div>
          </div>
        ))}
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 14, flexWrap: 'wrap', marginTop: 10 }}>
        <Legend c="var(--cyan-400)" name="F1" />
        <Legend c="rgba(0,218,243,0.3)" name="Precision" />
        <Legend c="rgba(179,157,251,0.5)" name="Recall" />
        <span style={{ fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>
          Hollow point = matching constants changed at that version.
        </span>
      </div>
    </div>
  );
}

function Legend({ c, name }: { c: string; name: string }) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, fontSize: 10.5, fontWeight: 700, color: 'var(--text-tertiary)' }}>
      <span style={{ width: 9, height: 9, borderRadius: 2, background: c, flexShrink: 0 }} />{name}
    </span>
  );
}

import { useCallback, useEffect, useState } from 'react';
import { fetchEvalRuns, fetchFixtures, fetchFights } from '../services/api';
import type { EvalRunSummary, FixtureSummary } from '../types/EvalRun';
import type { Fight } from '../types/Fight';
import { useWindowWidth } from '../hooks/useWindowWidth';
import FixtureTable from '../components/accuracy/FixtureTable';
import HeadlineF1 from '../components/accuracy/HeadlineF1';
import NotMeasurable from '../components/accuracy/NotMeasurable';
import ProvenanceLine from '../components/accuracy/ProvenanceLine';
import VersionTrendChart from '../components/accuracy/VersionTrendChart';

/**
 * Training Lab, Section E only ("Pipeline accuracy") — see
 * ~/.claude/plans/i-have-now-reference-radiant-salamander.md. Sections
 * A-D/F/G of the full design need labelled-data volume/infrastructure this
 * app doesn't have yet; this page covers only what the current fixtures
 * (a labelled reference fight scored against a re-uploaded, AI-processed
 * copy of itself) can honestly show — E0/E1/E2/E8.
 */
export default function PipelineAccuracy() {
  const width = useWindowWidth();
  const isMobile = width < 640;

  const [fixtures, setFixtures] = useState<FixtureSummary[]>([]);
  const [fights, setFights] = useState<Fight[]>([]);
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [runs, setRuns] = useState<EvalRunSummary[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadFixtures = useCallback(() => {
    setLoading(true);
    Promise.all([fetchFixtures(), fetchFights()])
      .then(([fx, fl]) => {
        setFixtures(fx);
        setFights(fl);
        setSelectedId((prev) => {
          if (prev !== null && fx.some((f) => f.reference_fight_id === prev)) return prev;
          const measurable = fx.find((f) => f.is_measurable);
          return (measurable ?? fx[0])?.reference_fight_id ?? null;
        });
      })
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'))
      .finally(() => setLoading(false));
  }, []);

  useEffect(() => { loadFixtures(); }, [loadFixtures]);

  const selected = fixtures.find((f) => f.reference_fight_id === selectedId) ?? null;

  useEffect(() => {
    if (!selected || !selected.is_measurable) {
      setRuns([]);
      return;
    }
    fetchEvalRuns(selected.reference_fight_id)
      .then(setRuns)
      .catch((err) => setError(err instanceof Error ? err.message : 'Unknown error'));
  }, [selected]);

  const candidates = fights.filter((f) => f.purpose === 'ai_labeled' && f.state === 'completed');

  return (
    <div style={{ maxWidth: 1440, margin: '0 auto', padding: isMobile ? '14px 13px 60px' : '22px 30px 80px', width: '100%' }}>
      <div style={{ marginBottom: 16 }}>
        <h1 className="font-display" style={{ fontSize: isMobile ? 30 : 40, lineHeight: 0.94, margin: 0, color: 'var(--text-primary)' }}>
          PIPELINE ACCURACY
        </h1>
        <p style={{ margin: '5px 0 0', fontSize: 12.5, fontWeight: 600, color: 'var(--text-muted)' }}>
          Reference fixtures scored against pipeline predictions, across versions
        </p>
      </div>

      {loading && <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading…</div>}
      {error && <div style={{ fontSize: 13, color: 'var(--red-500)', marginBottom: 14 }}>{error}</div>}

      {!loading && fixtures.length === 0 && (
        <div className="glass" style={{ padding: '20px 22px', fontSize: 13, color: 'var(--text-muted)' }}>
          No labelled reference fixture exists yet. Upload a fight as "Self-annotate → Reference" and
          finish labelling it to create one.
        </div>
      )}

      {fixtures.length > 0 && (
        <div className="glass" style={{ padding: '20px 22px 22px', marginBottom: 16 }}>
          <div className="label" style={{ marginBottom: 12 }}>Fixtures</div>
          <FixtureTable fixtures={fixtures} selectedId={selectedId} onSelect={setSelectedId} />
        </div>
      )}

      {selected && (
        <div className="glass" style={{ padding: '20px 22px 22px' }}>
          {!selected.is_measurable ? (
            <NotMeasurable fixture={selected} candidates={candidates} onScored={loadFixtures} />
          ) : runs.length > 0 ? (
            <>
              <div style={{ marginBottom: 16 }}>
                <ProvenanceLine run={runs[runs.length - 1]} />
              </div>
              <div style={{ marginBottom: 20 }}>
                <HeadlineF1 runs={runs} />
              </div>
              <div>
                <div className="label" style={{ marginBottom: 11 }}>Accuracy history — this fixture, every version</div>
                <VersionTrendChart runs={runs} />
              </div>
            </>
          ) : (
            <div style={{ fontSize: 13, color: 'var(--text-muted)' }}>Loading runs…</div>
          )}
        </div>
      )}
    </div>
  );
}

