import type { EvalReport } from '../../types/EvalRun';
import StatusBadge from './StatusBadge';

interface ClassificationBreakdownProps {
  strikes: EvalReport['strikes'];
}

const pct = (n: number, d: number) => (d > 0 ? `${((n / d) * 100).toFixed(1)}%` : null);

function Tile({ label, value, sub, status }: { label: string; value: React.ReactNode; sub: string; status?: 'none' }) {
  return (
    <div className="inner-tile" style={{ padding: '13px 15px', flex: 1, minWidth: 150 }}>
      <div className="label" style={{ marginBottom: 8 }}>{label}</div>
      {status ? (
        <StatusBadge status={status} size="sm">{value}</StatusBadge>
      ) : (
        <span className="font-display" style={{ fontSize: 28, lineHeight: 1, color: 'var(--text-primary)' }}>{value}</span>
      )}
      <div style={{ marginTop: 6, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>{sub}</div>
    </div>
  );
}

/** Section E3 — classification accuracy over matched strikes only. */
export default function ClassificationBreakdown({ strikes }: ClassificationBreakdownProps) {
  const familyPct = pct(strikes.family_correct, strikes.family_total);
  const targetPct = pct(strikes.target_correct, strikes.target_total);
  const cornerPct = pct(strikes.fighter_correct, strikes.fighter_total);

  return (
    <div>
      <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 12 }}>
        <Tile label="Strike family" value={familyPct ?? 'Not measurable'} sub={`${strikes.family_total} specific matches`} status={familyPct ? undefined : 'none'} />
        <Tile label="Target zone" value={targetPct ?? 'Not measurable'} sub={`${strikes.target_total} specific matches`} status={targetPct ? undefined : 'none'} />
        <Tile label="Landed vs missed" value="Not measurable" sub="labels deliberately record no outcome" status="none" />
        <Tile label="Grappling matches" value={strikes.nonspecific_matches} sub="non-specific — detection only" />
      </div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }}>
        <StatusBadge status="circular" title="The labeller reads the corner off the pipeline's own overlay, so a tracker swap is copied into the label and cancels out.">Circular</StatusBadge>
        <span style={{ fontSize: 11.5, fontWeight: 600, color: 'var(--text-tertiary)' }}>
          Corner read-back {cornerPct ?? '—'} ({strikes.fighter_total} matches) — not attribution accuracy.
          Use corner-swap spans instead.
        </span>
      </div>
    </div>
  );
}

interface OffsetDotStripProps {
  /** Signed (predicted - truth) frame offsets for every matched strike. */
  offsets: number[];
}

/** Section E5 — a dot strip of signed timing offsets, -N to +N frames around
 * a zero line, with bias (systematic lag, subtract once) and jitter (genuine
 * spread) called out separately. */
export default function OffsetDotStrip({ offsets }: OffsetDotStripProps) {
  if (offsets.length === 0) {
    return <div style={{ fontSize: 11.5, fontWeight: 600, color: 'var(--text-muted)' }}>No matched strikes to time yet.</div>;
  }

  const sorted = [...offsets].sort((a, b) => a - b);
  const median = (arr: number[]) => {
    const mid = Math.floor(arr.length / 2);
    return arr.length % 2 ? arr[mid] : (arr[mid - 1] + arr[mid]) / 2;
  };
  const bias = median(sorted);
  const jitter = median(offsets.map((o) => Math.abs(o)).sort((a, b) => a - b));
  const bound = Math.max(12, ...offsets.map((o) => Math.abs(o)));

  const W = 480, H = 46, padX = 16;
  const x = (o: number) => padX + ((o + bound) / (bound * 2)) * (W - padX * 2);

  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H}`} width="100%" height={H} preserveAspectRatio="xMidYMid meet" style={{ display: 'block' }}>
        <line x1={x(0)} x2={x(0)} y1={4} y2={H - 4} stroke="rgba(255,255,255,0.14)" strokeWidth="1" />
        {offsets.map((o, i) => (
          <circle key={i} cx={x(o)} cy={H / 2 + (Math.random() - 0.5) * 14} r={2.5} fill="var(--cyan-400)" fillOpacity={0.55}>
            <title>{o > 0 ? '+' : ''}{o}f</title>
          </circle>
        ))}
      </svg>
      <div style={{ marginTop: 6, fontSize: 11.5, fontWeight: 700, color: 'var(--text-secondary)' }}>
        bias {bias > 0 ? '+' : ''}{bias.toFixed(1)}f (systematic lag) · jitter {jitter.toFixed(1)}f (spread)
      </div>
      <div style={{ marginTop: 2, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>
        Bias is a constant to subtract once, not a reason to widen the tolerance.
      </div>
    </div>
  );
}

