import type { EvalReport } from '../../types/EvalRun';
import StatusBadge from './StatusBadge';

interface RoundsCheckProps {
  rounds: EvalReport['rounds'];
}

/** Section E7 — round count + per-round IoU, with "Seeded — not verified"
 * standing in for the IoU on any round whose label bounds are still
 * byte-identical to what they were auto-seeded from (circular otherwise). */
export default function RoundsCheck({ rounds }: RoundsCheckProps) {
  const countOk = rounds.gt_count === rounds.pred_count;
  return (
    <div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 10 }}>
        <span style={{ fontSize: 12, fontWeight: 700, color: 'var(--text-secondary)' }}>
          truth {rounds.gt_count} · predicted {rounds.pred_count}
        </span>
        <StatusBadge status={countOk ? 'good' : 'critical'} size="sm">{countOk ? 'Count OK' : 'Count WRONG'}</StatusBadge>
      </div>
      <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
        {rounds.matched.map(([num, iou, dstart, dend, seeded]) => (
          <div key={num} style={{ display: 'flex', alignItems: 'center', gap: 10, fontSize: 11.5, fontWeight: 600, color: 'var(--text-tertiary)' }}>
            <span style={{ fontWeight: 800, color: 'var(--text-primary)', minWidth: 56 }}>Round {num}</span>
            {seeded ? (
              <StatusBadge status="warning" size="sm" title="Still byte-identical to the pipeline's own segmentation — a labeller hasn't confirmed it. Scoring its IoU would be circular.">
                Seeded — not verified
              </StatusBadge>
            ) : (
              <span style={{ fontVariantNumeric: 'tabular-nums' }}>IoU {(iou * 100).toFixed(1)}%</span>
            )}
            <span style={{ fontVariantNumeric: 'tabular-nums', color: 'var(--text-muted)' }}>
              start {dstart >= 0 ? '+' : ''}{dstart.toFixed(2)}s · end {dend >= 0 ? '+' : ''}{dend.toFixed(2)}s
            </span>
          </div>
        ))}
      </div>
      {!countOk && (
        <p style={{ margin: '10px 0 0', fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)', lineHeight: 1.5 }}>
          Mean IoU stays high when one round is split into several — the count is what catches that.
        </p>
      )}
    </div>
  );
}

import type { EvalReport } from '../../types/EvalRun';

interface StateDumbbellProps {
  state: EvalReport['state'];
}

function Row({ label, truth, pred, unit, max, warn }: { label: string; truth: number; pred: number; unit: string; max: number; warn?: string }) {
  const x = (v: number) => Math.min(100, (v / max) * 100);
  return (
    <div style={{ marginBottom: 14 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 6 }}>
        <span style={{ fontSize: 11, fontWeight: 700, color: 'var(--text-secondary)' }}>{label}</span>
        <span style={{ fontSize: 11, fontWeight: 700, fontVariantNumeric: 'tabular-nums', color: 'var(--text-tertiary)' }}>
          truth {truth.toFixed(1)}{unit} · predicted {pred.toFixed(1)}{unit}
        </span>
      </div>
      <div style={{ position: 'relative', height: 6, background: 'rgba(255,255,255,0.06)', borderRadius: 3 }}>
        <div style={{ position: 'absolute', top: -3, left: `${x(truth)}%`, width: 12, height: 12, borderRadius: '50%', background: 'var(--purple-600)', transform: 'translateX(-50%)' }} title="Truth" />
        <div style={{ position: 'absolute', top: -3, left: `${x(pred)}%`, width: 12, height: 12, borderRadius: '50%', background: 'var(--cyan-400)', transform: 'translateX(-50%)' }} title="Predicted" />
      </div>
      {warn && <div style={{ marginTop: 6, fontSize: 10.5, fontWeight: 700, color: '#fab219' }}>⚠ {warn}</div>}
    </div>
  );
}

/** Section E6 — fight-state leads with stability (transition rate, dwell
 * time), not raw per-frame accuracy, which is dominated by the majority
 * state and hides a flapping state machine (honesty rule 7). */
export default function StateDumbbell({ state }: StateDumbbellProps) {
  const flapping = state.pred_transitions_per_min > 3 * Math.max(state.gt_transitions_per_min, 0.1);
  const accuracy = state.frames_scored > 0 ? (state.frames_correct / state.frames_scored) * 100 : null;

  return (
    <div>
      <Row
        label="Transitions per minute"
        truth={state.gt_transitions_per_min}
        pred={state.pred_transitions_per_min}
        unit="/min"
        max={Math.max(state.gt_transitions_per_min, state.pred_transitions_per_min, 1) * 1.2}
        warn={flapping ? 'predicted state flaps far faster than reality — hysteresis is not holding' : undefined}
      />
      <Row
        label="Median dwell"
        truth={state.gt_median_dwell_secs}
        pred={state.pred_median_dwell_secs}
        unit="s"
        max={Math.max(state.gt_median_dwell_secs, state.pred_median_dwell_secs, 1) * 1.2}
      />
      <div style={{ marginTop: 10, fontSize: 10.5, fontWeight: 600, color: 'var(--text-muted)' }}>
        Per-frame accuracy {accuracy != null ? `${accuracy.toFixed(1)}%` : '—'} ({state.frames_scored} frames) — dominated by the most common state, shown small on purpose.
      </div>
    </div>
  );
}

import type { LabelStrike, PredictedStrikeItem } from '../../types/EvalRun';

interface WorstListProps {
  title: string;
  fps: number;
  items: (LabelStrike | PredictedStrikeItem)[];
  emptyLabel: string;
  limit?: number;
}

const fmtClock = (frame: number, fps: number) => {
  const t = frame / fps;
  const m = Math.floor(t / 60);
  const s = (t % 60).toFixed(2).padStart(5, '0');
  return `${m}:${s}`;
};

/** Section E9 — worst misses (false negatives) / false positives, the
 * review queue. Shared by both lists — same row shape either side. */
export default function WorstList({ title, fps, items, emptyLabel, limit = 8 }: WorstListProps) {
  const shown = items.slice(0, limit);
  return (
    <div>
      <div className="label" style={{ marginBottom: 9 }}>{title} ({items.length})</div>
      {shown.length === 0 ? (
        <div style={{ fontSize: 11.5, fontWeight: 600, color: 'var(--text-muted)' }}>{emptyLabel}</div>
      ) : (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          {shown.map((it, i) => (
            <div key={i} style={{
              display: 'flex', alignItems: 'center', gap: 9, padding: '7px 10px',
              borderRadius: 8, background: 'rgba(0,0,0,0.24)', border: '1px solid var(--border-subtle)',
              fontSize: 11.5, fontWeight: 600, fontVariantNumeric: 'tabular-nums',
            }}>
              <span style={{ color: 'var(--text-muted)', minWidth: 62 }}>{fmtClock(it.frame, fps)}</span>
              <span style={{
                width: 8, height: 8, borderRadius: '50%', flexShrink: 0,
                background: it.fighter === 'red' ? 'var(--f-red)' : 'var(--f-blue)',
              }} title={it.fighter} />
              <span style={{ color: 'var(--text-secondary)' }}>
                {'action' in it ? it.action : `${it.family}_${it.target}`}
              </span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

